using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class PrivateStanddownTests
{
    static readonly EntityId Head=new("person:nobunaga"),Own=new("org:standdown"),Oda=new("org:oda");
    internal static WorldSession Start(bool policy=true){var p=NewGameWorldTests.Officer(role:StartTemplate.Daimyo,site:"site:fork");var setup=NewGameWorldTests.Setup([p],[new(p.Id,Own.Value,[p.Site],false)]);var s=new WorldSession(NewGameWorld.Create(setup.World,setup.Registered,p.Id,npcRoutinePolicy:NewGameNpcRoutine.Policy,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,worldArmyPolicy:NpcArmies.CompactCombatPolicy,informationPolicy:PrivateInformation.Policy,standdownPolicy:policy?PrivateStanddown.Policy:null));Advance(s,8);Assert.Equal(ResultCode.Accepted,s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:standdown-visit","castle"),s.Revision).Code);Advance(s,s.Seconds+1);Advance(s,s.DiagnosticSnapshot().Branches!.Journeys.Single().Legs[^1].EndAt);return s;}
    static void Advance(WorldSession s,long at){while(s.Seconds<at){long old=s.Seconds;s.SetPaused(false);s.AdvanceTo(at,100000);Assert.True(s.Seconds>old);}}
    static void EstablishContact(WorldSession s){var q=new EntityId("request:standdown-info");Assert.Equal(ResultCode.Accepted,s.ContactForInformation(new(q,Head,InformationAction.Ask),s.PlayerControl,s.Revision).Code);Assert.Equal(ResultCode.Accepted,s.ContactForInformation(new(new("request:standdown-info-accept"),Head,InformationAction.Accept,q),s.PlayerControl,s.Revision).Code);Advance(s,s.Seconds+1);var m=s.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Kind==PrivateInformation.Kind);Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,new(m.Id),s.Revision).Code);Assert.Equal(ResultCode.Accepted,s.ContactForInformation(new(new("request:standdown-info-pay"),Head,InformationAction.Pay,q),s.PlayerControl,s.Revision).Code);}
    static CommandResult Act(WorldSession s,StanddownAction action,EntityId? quote=null,int hours=0,string? id=null)=>s.NegotiateStanddown(new(new(id??"request:standdown/"+s.Revision),Head,action,quote,hours),s.PlayerControl,s.Revision);
    static EntityId Agree(WorldSession s){EstablishContact(s);var r=Act(s,StanddownAction.Ask,hours:1);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);var id=s.StanddownView().Last().Quote;r=Act(s,StanddownAction.Accept,id);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);return id;}
    [Fact]public void PriorPaidContactIsRequiredAndMerelyAskingSpendsNoMoney(){var s=Start();var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,Act(s,StanddownAction.Ask,hours:1).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));EstablishContact(s);long money=NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl);Assert.Equal(ResultCode.Accepted,Act(s,StanddownAction.Ask,hours:1).Code);Assert.Equal(money,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));Assert.False(PrivateStanddown.ShouldWait(s.DiagnosticSnapshot(),Head,s.Seconds,s.Revision));}
    [Fact]public void AcceptanceMovesPrivateMoneyAndDoesNotTransferHouseTroopsOrDeclarePeace(){var s=Start();var before=s.DiagnosticSnapshot();Agree(s);var w=s.DiagnosticSnapshot();Assert.Equal(880,NewGameWork.Balance(w,s.PlayerControl));Assert.Equal(1120,NewGameWork.Balance(w,Head));Assert.True(PrivateStanddown.ShouldWait(w,Head,s.Seconds,s.Revision));Assert.False(PrivateStanddown.ShouldWait(w,new("person:shingen"),s.Seconds,s.Revision));Assert.Empty(w.Units);Assert.Equal(ContractJson.Write(before.Memberships),ContractJson.Write(w.Memberships));Assert.Equal(ContractJson.Write(before.ServiceBonds),ContractJson.Write(w.ServiceBonds));Assert.Null(w.FactionStances);Assert.DoesNotContain(w.Messaging.Messages,m=>m.Kind.Contains("standdown"));}
    [Theory][InlineData(0)][InlineData(-1)][InlineData(25)]public void UnsupportedHoursDoNotChangeWorld(int hours){var s=Start();EstablishContact(s);var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,Act(s,StanddownAction.Ask,hours:hours).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void StaleRevisionAndIdempotentAcceptDoNotDoublePay(){var s=Start();EstablishContact(s);Assert.Equal(ResultCode.Accepted,Act(s,StanddownAction.Ask,hours:1).Code);var q=s.StanddownView().Single().Quote;var i=new StanddownInput(new("request:standdown-stable"),Head,StanddownAction.Accept,q);Assert.Equal(ResultCode.StateChanged,s.NegotiateStanddown(i,s.PlayerControl,999).Code);Assert.Equal(ResultCode.Accepted,s.NegotiateStanddown(i,s.PlayerControl,s.Revision).Code);Assert.Equal(ResultCode.AlreadyAccepted,s.NegotiateStanddown(i,s.PlayerControl,s.Revision).Code);Assert.Equal(ResultCode.IdPayloadConflict,s.NegotiateStanddown(i with{Hours=2},s.PlayerControl,s.Revision).Code);Assert.Equal(880,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));}
    [Fact]public void ConfirmDeadlineAndOverlappingAgreementsAreRejected(){var s=Start();EstablishContact(s);Assert.Equal(ResultCode.Accepted,Act(s,StanddownAction.Ask,hours:1).Code);var q=s.StanddownView().Single().Quote;Advance(s,s.Seconds+31);Assert.Equal(ResultCode.NotAvailable,Act(s,StanddownAction.Accept,q).Code);Assert.Equal(ResultCode.Accepted,Act(s,StanddownAction.Ask,hours:1).Code);Assert.Equal(ResultCode.Accepted,Act(s,StanddownAction.Accept,s.StanddownView().Last().Quote).Code);Assert.Equal(ResultCode.NotAvailable,Act(s,StanddownAction.Ask,hours:1).Code);}
    [Fact]public void HostileNpcActuallyWaitsUntilExactExpiryThenUsesSameCommonArmyAndRoad(){var s=Start();Agree(s);long until=s.StanddownView().Single().Until!.Value;Assert.Equal(ResultCode.Accepted,s.ProclaimFactionStance(new(new(new("decision:standdown-threat"),FactionStanceAction.DeclareHostile,Own,Oda,s.Seconds,until+100000),new(new("request:standdown-threat"),new("decision:standdown-threat"))),s.PlayerControl,s.Revision).Code);Advance(s,s.Seconds+8);Assert.Contains(FactionStances.Truth(s.DiagnosticSnapshot(),s.Seconds),h=>h.FromOwner==Oda);Assert.Empty(NpcArmies.Musters(s.DiagnosticSnapshot()));Advance(s,until-1);Assert.Empty(NpcArmies.Musters(s.DiagnosticSnapshot()));s.SetPaused(true);var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"standdown-save-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(s,"holding",w.WorldId).Published);var host=new WorldSessionHost(Start());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("holding"),host.Current,host.Current.Revision));Export(s,host.Current,"standdown-holding");Advance(s,until+2);Advance(host.Current,until+2);w=s.DiagnosticSnapshot();Assert.Single(NpcArmies.Musters(w));Assert.Equal(100,w.Units.Sum(u=>u.Soldiers));Assert.Contains(w.Branches!.Journeys,j=>j.Actor==Head);Assert.False(PrivateStanddown.ShouldWait(w,Head,s.Seconds,s.Revision));Assert.Equal(ContractJson.Write(w),ContractJson.Write(host.Current.DiagnosticSnapshot()));Assert.Equal(ContractJson.Write(s.StanddownView()),ContractJson.Write(host.Current.StanddownView()));s.SetPaused(true);Assert.True(store.Save(s,"released",w.WorldId).Published);var again=new WorldSessionHost(Start());Assert.Equal(ResultCode.Accepted,again.CommitLoad(store.Prepare("released"),again.Current,again.Current.Revision));Export(s,again.Current,"standdown-released");Assert.Equal(ResultCode.NotAvailable,Act(s,StanddownAction.Ask,hours:1).Code);}
    [Fact]public void ForeignActorAndNonHeadCannotMakeAnotherPersonsPromise(){var s=Start();EstablishContact(s);Assert.Equal(ResultCode.NotAvailable,s.NegotiateStanddown(new(new("request:not-own"),Head,StanddownAction.Ask,null,1),Head,s.Revision).Code);Assert.Equal(ResultCode.NotAvailable,s.NegotiateStanddown(new(new("request:self"),s.PlayerControl,StanddownAction.Ask,null,1),s.PlayerControl,s.Revision).Code);}
    [Fact]public void FeeHoursAndPaymentSourceCannotBeTampered(){var s=Start();Agree(s);var w=s.DiagnosticSnapshot();w.Standdown=w.Standdown! with{Quotes=[w.Standdown.Quotes.Single() with{Hours=24}]};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));w=s.DiagnosticSnapshot();w.Standdown=w.Standdown! with{Quotes=[w.Standdown.Quotes.Single() with{Payment=new("request:fake-payment")}]};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void OldNullPolicyRetainsBytesAndRejectsInjection(){var s=Start(false);var bytes=ContractJson.Write(s.DiagnosticSnapshot());Assert.DoesNotContain("StanddownPolicy",System.Text.Encoding.UTF8.GetString(bytes));Assert.Equal(bytes,ContractJson.Write(new WorldSession(ContractJson.Read<ContractWorld>(bytes)).DiagnosticSnapshot()));Assert.Equal(ResultCode.NotAvailable,Act(s,StanddownAction.Ask,hours:1).Code);var w=s.DiagnosticSnapshot();w.Standdown=new(1,PrivateStanddown.Policy,[],[]);Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void QuotationCannotPromiseAnotherPersonsHoursOrBeAcceptedRemotely(){var s=Start();EstablishContact(s);Act(s,StanddownAction.Ask,hours:1);var q=s.StanddownView().Single().Quote;Assert.Equal(ResultCode.NotAvailable,Act(s,StanddownAction.Accept,q,hours:24).Code);Assert.Equal(ResultCode.Accepted,s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:standdown-away","fork"),s.Revision).Code);Advance(s,s.Seconds+2);Assert.Equal(ResultCode.NotAvailable,Act(s,StanddownAction.Accept,q).Code);}
    static void Export(WorldSession a,WorldSession b,string name){var dir=Environment.GetEnvironmentVariable("HAKUTAI_WORLD_CLASH_QA_DIR");if(string.IsNullOrWhiteSpace(dir))return;Directory.CreateDirectory(dir);foreach(var row in new[]{(s:a,tag:"before"),(s:b,tag:"restored")})File.WriteAllBytes(Path.Combine(dir,name+"."+row.tag+".json"),ContractJson.Write(row.s.DiagnosticSnapshot()));}
}
